package glitch

import data.glitch_lib

credential_patterns := {
    "password", "passwd", "pwd", "secret", "token", "key",
    "api_key", "access_key", "auth", "credential", "login",
    "admin_password", "db_password", "api_token", "default_password",
    "master_password", "connection_string", "jdbc_url", "dsn",
    "ssh_key", "private_key", "client_secret"
}

is_hardcoded_credential(value) {
    value.ir_type == "String"
    count(value.value) > 0
} else {
    value.ir_type == "Integer"
    count(value.value) > 0
}

has_credential_name(attr_name) {
    regex.match(sprintf("(?i).*%s.*", [credential_patterns[_]]), attr_name)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    has_credential_name(attr.name)
    is_hardcoded_credential(attr.value)

    result := {
        "type": "sec_hard_pass",
        "element": attr,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Avoid hard-coding passwords or secrets in the code. (CWE-259)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    has_credential_name(var.name)
    is_hardcoded_credential(var.value)

    result := {
        "type": "sec_hard_pass",
        "element": var,
        "path": parent.path,
        "description": "Use of Hard-coded Password - Avoid hard-coding passwords or secrets in the code. (CWE-259)"
    }
}

